      "id": "chapter.365_days",
      "tiers": [
        {
          "id": "chapter.365_days:t1",
          "title": "Закладка в пути",
          "phrase": "У тебя 50% главы о годе пути и 40 тренировочных днях: в зачёт идут обе части. Календарь уже придерживает закладку.",
          "imagePrompt": "A tortoise pushes a little wooden book cart carrying an enormous half-open journal; a spring twig and an autumn leaf peek between its pages, while the tortoise steadies a loose bookmark with one determined paw.",
          "fishMarkup": "[warm]У тебя 50% главы о годе пути и 40 тренировочных днях: в зачёт идут обе части. Календарь уже придерживает закладку.",
          "audioText": "У тебя 50% главы о годе пути и 40 тренировочных днях: в зачёт идут обе части. Календарь уже придерживает закладку."
        },
        {
          "id": "chapter.365_days:t2",
          "title": "Сюжет набирает ход",
          "phrase": "На твоём счету 75% главы о годе пути и 40 тренировочных днях. Время и тренировочные дни вместе двигают сюжет — календарь читает стоя.",
          "imagePrompt": "A tortoise climbs a staircase of thick journals stacked on its wooden book cart, using a long bookmark as a handrail; near the top, it reaches toward an open volume with a pine sprig tucked between its pages.",
          "fishMarkup": "[confident]На твоём счету <emphasis>75% главы</emphasis> о годе пути и 40 тренировочных днях. [playful]Время и тренировочные дни вместе двигают сюжет — календарь читает стоя.",
          "audioText": "На твоём счету 75% главы о годе пути и 40 тренировочных днях. Время и тренировочные дни вместе двигают сюжет — календарь читает стоя."
        },
        {
          "id": "chapter.365_days:t3",
          "title": "Календарь просит автограф",
          "phrase": "За тобой год пути и 40 тренировочных дней — ты закрыл 100% главы. Календарь встал за автографом — с раскладушкой.",
          "imagePrompt": "A tortoise turns its wooden book cart into an author signing booth, sitting behind an enormous open journal with a quill; an eager walking desk calendar with blank pages unfolds a camping cot at the head of the queue.",
          "fishMarkup": "[triumphant]За тобой год пути и 40 тренировочных дней — ты закрыл <emphasis>100% главы</emphasis>. [playful]Календарь встал за автографом — <slow>с раскладушкой.</slow>",
          "audioText": "За тобой год пути и 40 тренировочных дней — ты закрыл 100% главы. Календарь встал за автографом — с раскладушкой."
        }
      ]
    },
    {
      "id": "chapter.foundation",
      "tiers": [
        {
          "id": "chapter.foundation:t1",
          "title": "Первый замес",
          "phrase": "Твои 50% главы «Фундамент» складываются из прогресса к 15 тренировочным дням и 4 активным неделям. Ты строишь базу, а не декорацию для гантели.",
          "imagePrompt": "A beaver builder kneels beside a partially laid square brick foundation, carefully placing a corner brick with a small trowel; a tiny kettlebell waits nearby on a wooden handcart as if expecting its own house.",
          "fishMarkup": "[warm]Твои 50% главы «Фундамент» складываются из прогресса к 15 тренировочным дням и 4 активным неделям. [playful]Ты строишь базу, а не декорацию для гантели.",
          "audioText": "Твои 50% главы «Фундамент» складываются из прогресса к 15 тренировочным дням и 4 активным неделям. Ты строишь базу, а не декорацию для гантели."
        },
        {
          "id": "chapter.foundation:t2",
          "title": "Кирпичи с характером",
          "phrase": "Ты собрал 75% главы «Фундамент», где учитываются и 15 тренировочных дней, и 4 активные недели. Кирпичи уже перестали делать вид, что они просто интерьер.",
          "imagePrompt": "A beaver builder uses a small lever to slide a broad slab onto a nearly completed brick foundation; the tiny kettlebell waits on its wooden handcart beside a short access ramp, with one unfinished corner still visible.",
          "fishMarkup": "[confident]Ты собрал <emphasis>75% главы «Фундамент»</emphasis>, где учитываются и 15 тренировочных дней, и 4 активные недели. [playful]Кирпичи уже перестали делать вид, что они просто интерьер.",
          "audioText": "Ты собрал 75% главы «Фундамент», где учитываются и 15 тренировочных дней, и 4 активные недели. Кирпичи уже перестали делать вид, что они просто интерьер."
        },
        {
          "id": "chapter.foundation:t3",
          "title": "Приёмка в тапочках",
          "phrase": "Ты собрал фундамент на 100%: 15 тренировочных дней и 4 активные недели. Лень пришла на приёмку — в каске и тапочках.",
          "imagePrompt": "A beaver builder proudly presents a massive completed brick foundation supporting one tiny kettlebell; a sloth inspector wearing a hard hat and oversized fluffy slippers examines it with a blank clipboard tucked under one arm.",
          "fishMarkup": "[triumphant]Ты собрал фундамент на <emphasis>100%</emphasis>: 15 тренировочных дней и 4 активные недели. [playful]Лень пришла на приёмку — <slow>в каске и тапочках.</slow>",
          "audioText": "Ты собрал фундамент на 100%: 15 тренировочных дней и 4 активные недели. Лень пришла на приёмку — в каске и тапочках."
        }
      ]
    }
  ]
}
